// Authored summaries, not executable defaults. Exact syntax/defaults always come
// from the selected binary. Sources were reviewed at this pinned upstream commit.
export const documentationRevision = '2130ca84764e75c7ae9106cec671caa73ddbe416';
export const documentationDate = '2026-10-15';
const source = path => `https://github.com/ggml-org/llama.cpp/blob/${documentationRevision}/${path}`;
const sources = {
  server: source('tools/server/README.md'), args: source('common/arg.cpp'),
  kv: source('src/llama-kv-cache.cpp'), quant: source('ggml/src/ggml-common.h'),
  performance: source('docs/development/token_generation_performance_tips.md'),
  speculative: source('examples/speculative/README.md'), media: source('tools/mtmd/README.md'),
};
const profiles = {
  cpu: ['CPU work may improve until memory bandwidth is saturated; doubling threads does not guarantee double speed.', 'No direct change to GPU weight or KV allocation.', 'Extra thread stacks/work buffers are small relative to weights; model size stays the same.'],
  scheduling: ['Changes how eagerly CPU work is scheduled, not how much model arithmetic is required.', 'No direct change to model/KV VRAM.', 'Usually little direct RAM change; CPU utilization, power and responsiveness matter more.'],
  batch: ['Mainly affects prompt ingestion and throughput; single-token generation is a different workload.', 'Larger physical batches can need larger compute buffers. Allocation is backend/model dependent.', 'CPU compute buffers can grow with the physical batch; this does not change weight size.'],
  weights: ['Moving weight computation to a sufficiently fast GPU can help; transfers or overfilled VRAM can make it slower.', 'Weight placement can change by gigabytes. Fit depends on tensor sizes, not only the number of layers.', 'CPU-resident weights can fall when offloaded, but mapped pages/OS file cache may remain.'],
  kv: ['Longer retained attention history usually means more work per token; cache placement/precision also affects bandwidth.', 'GPU-resident KV storage changes; the model weights do not. Size depends on context, layers and KV-head dimensions.', 'The same cache uses RAM when kept on CPU. Recurrent/hybrid/SWA models do not always follow dense-cache formulas.'],
  loading: ['Primarily changes startup, disk access and paging; it is not a fixed tokens/second multiplier.', 'For unchanged offload/model settings, weight VRAM usually stays similar.', 'Mapped address space is not resident RAM. Locked pages cannot be paged out; lazy reads trade RAM for disk access.'],
  hostcache: ['A reusable matching prefix can avoid prompt recomputation; a new unrelated prompt gets little benefit.', 'Host prompt-cache limits do not directly set the active GPU KV allocation.', 'This controls cached prompt/state storage in system memory; larger limits permit more RAM use.'],
  sample: ['Primarily changes which token is chosen, not model evaluation speed. Longer answers still take longer overall.', 'No direct change to model weights or reserved KV capacity.', 'Sampler/history state is usually small compared with model memory; some history windows add CPU work.'],
  format: ['Templates/constraints can change token counts or add parsing work. They do not make model inference intrinsically faster.', 'Weights are unchanged; longer prompts/outputs consume more of the configured context.', 'Text, parser and constraint buffers can grow; usually small compared with weights, except very complex constraints.'],
  network: ['Changes connectivity, API behavior or request handling rather than per-token model arithmetic.', 'No direct weight or KV-capacity change.', 'Connections, TLS and request buffers add workload-dependent overhead.'],
  log: ['Detailed output can add formatting and disk I/O overhead; disabling it is not a guaranteed inference speedup.', 'Normally no direct weight/KV allocation change.', 'Usually modest buffering; files consume disk. Separate server log files are outside launcher rotation/redaction.'],
  model: ['Architecture, size, quantization and storage determine load time and inference speed; the path/name itself has no speed multiplier.', 'A different model can change weight/KV VRAM by gigabytes. Check the selected GGUF and offload settings.', 'CPU weights/mapped files depend on the chosen model. Downloaded files also consume disk space.'],
  adapter: ['Adapters add loading work and may add inference operations; effect depends on rank/count/backend.', 'Adapter tensors add memory if placed on GPU; strength alone normally does not change their stored size.', 'Adapter/vector files and tensors add host memory; strength does not duplicate the base model.'],
  media: ['More image tokens or video frames add encoder and prompt-processing work, increasing time to first token.', 'Projector weights and encoder/attention buffers can add VRAM; changing resolution does not resize base text weights.', 'Decoded images, frames/audio and input buffers add RAM; long media can be substantial.'],
  spec: ['Extra proposal work helps only when enough tokens are accepted; otherwise speculation can slow generation.', 'A draft model and its KV/compute buffers can add VRAM; n-gram methods do not require a second weight model.', 'Draft weights, KV/history and lookup tables can add RAM. Speed gains are acceptance/model dependent.'],
  tools: ['External tools add their own network/process latency; enabling tools is not an inference acceleration setting.', 'No direct base-model allocation change; called tools can use independent GPU resources.', 'Tool processes/containers can consume additional RAM outside the model process.'],
  utility: ['Prints information or performs setup, often then exits; this is not a normal serving optimization.', 'Discovery may initialize a driver, but normally does not load model weights.', 'Mostly temporary command output/completion data; no persistent model allocation.'],
};
/** @type {Map<string,import('./option-guide-types').OptionGuide>} */
export const reviewedGuides = new Map();
function define(tab, category, group, resource, rows, refs=['server','args']) {
  for(const line of rows.trim().split('\n')) {
    const [flag,title,summary,change,scale]=line.split('|');
    if(!flag||!title||!summary||!change||!scale||reviewedGuides.has(flag))throw Error(`Invalid/duplicate option guide: ${flag}`);
    const [speed,vram,ram]=profiles[resource];
    reviewedGuides.set(flag,{flag,title,tab,category,group,summary,change,scale,speed,vram,ram,sources:refs.map(key=>sources[key]),reviewed:true});
  }
}
function variant(flag,base,{tab,category,group,title,prefix}) {
  const original=reviewedGuides.get(base);if(!original||reviewedGuides.has(flag))throw Error(`Invalid guide variant ${flag}`);
  reviewedGuides.set(flag,{...original,flag,tab:tab||original.tab,category:category||original.category,group:group||original.group,title,summary:`${prefix} ${original.summary}`,change:`${prefix} ${original.change}`});
}

define('performance','Performance','CPU threads','cpu',`
--threads|CPU generation threads|How many CPU workers evaluate each newly generated token.|Increase to use more cores; decrease if scheduling or memory bandwidth becomes the bottleneck. GPU-heavy runs can need fewer CPU threads.|Try 2 → 4 → 8 and compare generated tokens/s. More workers can be slower; start near physical-core count rather than assuming all logical threads are best.
--threads-batch|CPU prompt-processing threads|CPU workers used while reading the prompt in batches.|More workers may shorten prompt ingestion; fewer leave CPU capacity for other work. This is separate from generation threads.|Changing 4 → 8 doubles the requested worker count, not guaranteed prompt speed or RAM. Compare prompt tokens/s and time to first token.
`,['server','performance']);
define('performance','Performance','CPU placement & affinity','cpu',`
--cpu-mask|CPU affinity mask|Choose the exact CPU cores the main model may use, using a hexadecimal bit mask.|Adding bits permits more cores; removing bits restricts placement. A mask is not a thread-count setting.|For CPUs numbered 0–3, mask F permits those four cores. Choose according to your OS topology; a wider mask does not guarantee faster generation.
--cpu-range|CPU core range|Restrict the main model to a numbered range of CPU cores.|Widen the range to allow more cores; narrow it for isolation or locality. Also set a suitable thread count.|A range such as 0-3 allows four numbered CPUs; those may be logical siblings rather than four physical cores.
--cpu-strict|Strict CPU placement|Control whether workers strictly follow the requested CPU placement.|1 enforces placement more strictly; 0 permits normal flexibility. Strict placement can help locality or hurt load balancing.|This is a policy switch, not a RAM or thread multiplier. Compare both on your actual multi-core/NUMA layout.
--numa|NUMA memory policy|Choose how CPU workers and memory behave across NUMA nodes/sockets.|Distribute spreads work; isolate keeps work on the starting node; numactl follows the external CPU map. No mode is always fastest.|Most single-socket consumer PCs gain little. Cross-socket remote memory traffic can dominate; measure on the intended NUMA machine.
`,['server','performance']);
define('performance','Performance','Scheduling & polling','scheduling',`
--prio|CPU scheduling priority|How strongly the operating system favors main-model CPU work.|Higher priority favors this process under contention; lower priority makes it yield more readily to other applications.|The levels are discrete, not speed percentages. Realtime can make the desktop unresponsive; use normal unless measurements justify a change.
--poll|Generation busy polling|How actively workers spin while waiting for generation work.|Increase for less waiting latency at the cost of CPU time/power; decrease to let idle workers sleep more.|0 disables polling; 100 is the highest polling level, not 100% faster. Idle CPU use can change much more than tokens/s.
`);
for(const [flag,base,title] of [
 ['--cpu-mask-batch','--cpu-mask','Prompt CPU affinity mask'],['--cpu-range-batch','--cpu-range','Prompt CPU core range'],['--cpu-strict-batch','--cpu-strict','Strict prompt CPU placement'],['--prio-batch','--prio','Prompt scheduling priority'],['--poll-batch','--poll','Prompt busy polling'],
])variant(flag,base,{title,prefix:'Prompt-processing phase:'});
define('performance','Performance','Batching & concurrency','batch',`
--batch-size|Logical prompt batch|Maximum number of prompt tokens offered in one logical batch.|Increase to admit larger chunks and potentially better aggregate prompt throughput; decrease to limit work admitted at once. Actual execution is split by microbatch size.|2048 → 4096 doubles the logical ceiling. With microbatch fixed at 512 it need not double peak compute-buffer memory or token speed.
--ubatch-size|Physical prompt microbatch|Maximum prompt tokens actually processed together in one physical computation.|Increase for more parallel prompt computation and potentially larger temporary buffers; decrease to save working memory at the cost of more passes.|256 → 512 doubles the microbatch token ceiling. Temporary memory may grow, but its exact factor is backend/model dependent. Keep it at or below the logical batch.
--parallel|Concurrent request slots|How many requests the server may work on at once.|More slots can improve total service throughput but compete for compute and context capacity; fewer favor individual request latency.|1 → 4 means up to four slots, not four weight copies or four times the speed. With a fixed total context, per-slot room can fall; per-slot context controls can instead grow the pool.
--cont-batching|Continuous request batching|Let active/new requests share inference batches as slots become available.|On can improve multi-user utilization; off removes this dynamic batching behavior and may simplify comparison of isolated requests.|Most relevant with multiple simultaneous requests. A single chat is not guaranteed to become faster just by enabling it.
`);
define('performance','Performance','Startup','loading',`
--warmup|Warm up the model|Run a small initial evaluation before accepting normal work.|On adds startup work but can reduce first-request initialization delay; off reaches startup sooner but shifts that cost to an early request.|Changes startup/first-request latency rather than a fixed steady-state speed percentage. Measure both separately.
`);
define('context','Context & cache','Context capacity','kv',`
--ctx-size|Context length in tokens|Total token context available for prompt history and generated answers.|More context fits longer conversations/documents but uses more KV capacity and can make attention slower; less saves cache memory and limits retained text.|For the same dense-attention model/cache layout, 4096 → 8192 is approximately 2× KV capacity, not 2× total memory. Example: a 1 GiB KV cache becomes about 2 GiB; weights stay unchanged. 0 follows the model.
--kv-unified-per-slot|Context limit per slot|Set a token limit for each parallel request when using the supported shared KV pool.|A larger per-slot limit permits longer requests and can size a larger total pool; a smaller one saves capacity when the pool is derived from slot count.|With no explicit total context, 4 slots × 4096 tokens requires a 16384-token pool; 4 × 8192 requires 32768. An explicit context value and runtime version can change that interaction.
--kv-unified|Shared KV pool|Use a KV buffer that multiple request sequences can share.|On pools storage so slots can share available capacity; off uses the runtime's separate-sequence layout. This does not duplicate or quantize weights.|Pooling changes allocation/utilization, not a guaranteed memory percentage. Total context, slot count, per-slot limits and architecture still determine actual allocation.
--keep|Initial prompt tokens to retain|How much of the initial prompt survives when old context must be shifted.|More retained tokens protect the beginning/system prompt but leave less room for newer history; fewer let more of the original text be discarded.|Keeping 512 of a 4096-token window reserves roughly one eighth for initial tokens during shifting. It does not allocate an extra 512-token cache; -1 requests all initial tokens.
--context-shift|Shift a full context window|Allow old context to be dropped/rearranged to continue generating when the window fills.|On permits continuation but the model loses discarded history and shifting may cost time; off can stop at the configured limit.|A 4096-token cache remains bounded around its configured capacity. This does not provide unlimited memory or unlimited recall.
--swa-full|Full sliding-window cache|Use a full-size cache rather than the optimized smaller sliding-window arrangement where supported.|On retains a larger cache and can use much more memory; off permits the sliding-window optimization. Only models using that attention layout are affected.|There is no universal ratio: it depends on the attention window, layer mix and requested context. Do not apply the dense-cache estimate blindly to hybrid/SWA models.
`,['server','kv']);
define('context','Context & cache','KV cache precision & placement','kv',`
--cache-type-k|Key cache precision|Storage format for the attention key cache, separate from model-weight quantization.|Lower precision reduces this cache's memory/bandwidth but can reduce quality or add conversion work; higher precision uses more memory. Backend/model support varies.|Raw-storage estimate: f16 → q8_0 uses about 53%; q4_0 about 28%. A 2 GiB K payload becomes roughly 1.06 GiB or 0.56 GiB, before alignment/metadata. This changes K only, not total application memory.
--cache-type-v|Value cache precision|Storage format for the attention value cache, separate from the key cache.|Lower precision saves V-cache memory with possible quality/conversion costs; higher precision retains more detail and costs more memory. Quantized V can require compatible Flash Attention/backends.|If equal-sized K and V both change f16 → q8_0, a 2 GiB dense KV payload becomes roughly 1.06 GiB (53%); changing only V leaves about 1.53 GiB (77% combined), before overhead. q4_0 is about 28% per changed component; quality/speed are not guaranteed.
--kv-offload|Put KV cache on GPU|Control GPU placement of attention's stored keys/values; this is not the GPU layer-count setting.|On uses GPU memory for eligible KV storage and can reduce CPU transfers; off shifts eligible cache toward system RAM and can slow attention.|If 2 GiB of eligible KV storage moves off the GPU, VRAM may fall by about that cache amount and RAM rise correspondingly. Weight placement is unchanged; actual layer/backend eligibility matters.
--defrag-thold|Legacy KV defragmentation threshold|A legacy threshold for reorganizing fragmented KV storage.|This option is deprecated in the reviewed executable; changing it may be ignored. Check the selected executable's original help before using it.|No reliable modern tuning magnitude exists. Leave it unset and use supported context/cache controls instead.
`,['server','kv','quant']);
define('context','Context & cache','Prompt reuse & checkpoints','hostcache',`
--cache-prompt|Reuse matching prompts|Reuse already evaluated matching prompt tokens instead of computing them again.|On can shorten repeated-prefix prompt processing; off forces more recomputation and is useful for uncached benchmark comparisons.|A repeated 3000-token prefix in a 3200-token request may avoid much of those 3000 tokens' evaluation, not all generation work. Gains require an actual reusable match.
--cache-ram|Host prompt-cache budget|Maximum system-memory budget for saved prompt/state cache, in MiB.|Increase to retain more reusable states; decrease to limit host cache growth. 0 disables this cache and -1 removes the configured cap.|8192 MiB permits about 8 GiB of cache budget; 4096 permits about 4 GiB. This is a cache limit, not immediate allocation or a cap on total process RAM.
--cache-reuse|Minimum reusable chunk|Minimum token chunk worth trying to recover through KV shifting.|A lower positive threshold considers smaller reused chunks and can add lookup/shifting work; a higher one requires larger matches. 0 disables this reuse mode.|A threshold of 128 considers shorter matches than 512. Neither value guarantees a specific hit rate or speedup; prompt caching must be enabled.
--cache-idle-slots|Cache idle request slots|Save idle slot state in the prompt cache when new work needs the slot.|On can preserve reusable context while freeing a shared KV slot; off can require more later recomputation. Needs the host prompt cache.|Savings depend on matching future requests and the cache-ram budget. It does not increase the number of simultaneously executing slots.
--ctx-checkpoints|Context checkpoints per slot|Maximum intermediate context snapshots retained per request slot.|More checkpoints can help restore/reuse earlier state but add memory; fewer save snapshot memory and can increase recomputation.|32 → 64 doubles the checkpoint-count ceiling, not necessarily total RAM. Recurrent/hybrid state size and active slot count determine the cost.
--checkpoint-min-step|Checkpoint spacing in tokens|Minimum token distance between stored context checkpoints.|Increase to create snapshots less often and save overhead; decrease to retain finer recovery points. 0 removes the minimum spacing.|8192 → 4096 permits snapshots twice as often on a long sequence, up to the checkpoint-count limit. It does not halve generation time.
--slot-prompt-similarity|Prompt similarity for slot reuse|How much a request must resemble a slot's prompt before that slot is reused.|Higher thresholds demand closer matches and may reduce reuse; lower thresholds accept looser candidates. 0 disables this selection criterion.|0.10 is a similarity threshold, not a 10% speedup or 10% memory allocation. Compare cache hits/time to first token for your prompts.
--slot-save-path|Saved slot-cache directory|Directory used to save and restore slot KV state on disk.|Enabling a path supports persistence/reuse but adds disk I/O and storage; leaving it unset disables that path-based feature.|Files can be large and can contain prompt-derived state. Disk usage depends on saved context/cache format; this is separate from the RAM cache budget.
`,['server','kv']);
define('context','Context & cache','Extended context (model-specific)','kv',`
--rope-scaling|RoPE extension method|Choose the positional-encoding adjustment used for context extension.|none preserves unscaled positions; linear and yarn use different extension strategies. Changing it alone does not enlarge the allocated context.|Use the model's documented method. Extending beyond training context can reduce quality even when the prompt fits in memory.
--rope-scale|RoPE context scale|Model-specific factor used to extend the positional range.|A larger factor stretches the positional range further; a smaller factor stays closer to the original range, with model-dependent quality effects.|A factor of 2 requests roughly a 2× positional range, not 2× speed. Raising ctx-size separately raises actual cache allocation.
--rope-freq-base|RoPE base frequency|Base frequency used by supported positional-scaling methods.|Changing this alters positional behavior, not a simple speed/memory slider. Wrong values can harm long-context answers.|Use the model's metadata or recommended value. There is no generally correct higher/lower setting or universal performance gain.
--rope-freq-scale|RoPE inverse frequency scale|Frequency scale whose inverse controls the positional stretch.|Smaller positive values stretch farther; larger values stretch less. This is the inverse direction of rope-scale.|0.5 corresponds to a 2× positional-range factor; 0.25 to 4×. Cache size still comes from context settings, and answer quality is not guaranteed.
--yarn-orig-ctx|Original training context for YaRN|Reference training context used by YaRN scaling.|This should describe the model, not be increased to request a larger prompt. A wrong reference changes the scaling calculation.|0 reads the model training-context value. Set an explicit number only when the model's instructions require it.
--yarn-ext-factor|YaRN extrapolation mix|Blend interpolation and extrapolation when applying YaRN.|Increasing changes the mix toward extrapolation; 0 uses full interpolation. This is a positional-quality control, not a memory budget.|The reviewed runtime uses -1 for automatic behavior. Use model-specific guidance; no universal percentage improvement exists.
--yarn-attn-factor|YaRN attention magnitude|Scale the attention magnitude used with YaRN extension.|Higher/lower values alter attention weighting and can affect output quality; neither direction guarantees faster inference.|Keep the model/automatic value unless its extension recipe specifies otherwise. It does not directly allocate more KV capacity.
--yarn-beta-slow|YaRN slow correction bound|One bound controlling which positional dimensions receive YaRN correction.|Changes the correction distribution; it is not a token-count, thread or memory multiplier.|Tune together with beta-fast using the model's documented recipe. Leave automatic/model values for ordinary use.
--yarn-beta-fast|YaRN fast correction bound|The other bound controlling YaRN's positional correction distribution.|Changes positional correction relative to beta-slow; unsuitable bounds can reduce long-context quality.|There is no safe universal higher-is-better rule. It does not independently enlarge the model's trained context or cache.
`,['server','args']);
define('gpu','GPU & memory','Weight placement','weights',`
--gpu-layers|GPU weight layers|How many model layers' weights/work are offloaded to GPU. KV cache is a separate control.|More generally moves weight work from CPU to GPU and consumes VRAM; fewer can fit smaller GPUs but leave more CPU work. GPU speed/interconnect and memory fit determine the gain.|Illustration only: 10 more layers averaging 100 MiB add about 1000 MiB (0.98 GiB) of GPU weights. Layers are unequal and extra tensors/buffers exist; 20 → 40 layers is not a guaranteed 2× speedup.
--device|GPU devices to use|Choose the backend devices allowed to hold/run offloaded model work.|Add devices to make multi-GPU placement possible; select none for CPU execution. A list by itself does not choose a balanced split.|Device names must come from this executable's list-devices output. More GPU memory can fit larger models, but communication can erase speed gains.
--override-tensor|Per-tensor device placement|Map named tensor patterns to a specific backend buffer type.|Moves matching tensors toward a chosen device/CPU memory, overriding normal placement. Poor maps can add frequent transfers.|Memory moves by the actual matched tensor bytes, not by a fixed percentage. This is an expert setting; verify the placement in startup output.
--cpu-moe|Keep all MoE expert weights on CPU|Keep mixture-of-experts weights in system memory instead of putting them all on GPU.|On can save substantial VRAM but makes expert evaluation/transfers depend on CPU/RAM bandwidth; off permits normal GPU placement.|Savings can be gigabytes for large MoE models, but expert sizes differ. This does not apply equivalently to dense FFN models.
--n-cpu-moe|MoE layers with CPU experts|Keep expert weights for the first N MoE layers on CPU.|Increase N to trade more GPU weight memory for CPU/RAM work; decrease to allow more GPU placement.|If five affected layers hold 200 MiB of experts each, their weight placement shifts by about 1 GiB. This is an illustration; use actual tensor sizes.
--n-cpu-ffn|Dense FFN layers on CPU|Keep feed-forward weights for the first N dense-model layers on CPU.|More CPU FFN layers can reduce VRAM and slow GPU-centric inference; fewer keep more FFN work on GPU. MoE experts use their separate setting.|Memory changes by the FFN tensors in the selected layers, not entire layers or the model's parameter count alone.
--moe-cache-mib|GPU cache for CPU experts|Reserve a GPU cache for MoE experts otherwise kept on CPU.|Increase to retain more expert data on GPU and potentially reduce transfers; decrease to leave more VRAM for other buffers. 0 disables it.|1024 → 2048 requests an extra 1024 MiB (1 GiB) cache budget across the configured devices. Hit rate determines whether that memory buys useful speed.
`,['server','performance','args']);
define('gpu','GPU & memory','Multi-GPU allocation','weights',`
--split-mode|How multiple GPUs share work|Choose a single GPU, layer split, row split or experimental tensor split.|Layer/row/tensor schemes distribute computation differently. More parallelism also introduces communication and mode-specific buffers.|Layer splitting is not equivalent to adding all GPUs' bandwidth. Benchmark the actual PCIe/NVLink topology; tensor mode is experimental in the reviewed build.
--tensor-split|GPU memory proportions|Relative proportions of model placement across the selected GPUs.|Increase one GPU's share to move more eligible tensors there; reduce it when that GPU needs headroom. Values are ratios, not GiB.|3,1 targets about 75%/25% of the distributed portion, not 3 GiB/1 GiB. Some tensors, KV and intermediate buffers have separate placement rules.
--main-gpu|Primary GPU index|Choose the single GPU or the device for shared/intermediate work in supported split modes.|Changing the index can move a concentration of work/memory. It does not add GPUs or increase their memory.|Index 0 → 1 selects a different device, not higher performance. Its exact effect depends on split mode; some modes ignore it.
`);
define('gpu','GPU & memory','Attention & automatic fitting','weights',`
--flash-attn|Flash Attention|Use a fused attention implementation when supported by the backend/model.|On can reduce attention temporary buffers and improve long-context processing; off uses the alternative path; auto lets the runtime decide.|It does not shrink model weights or change the mathematical KV element count. Gains and supported cache formats depend on GPU/backend; no fixed speed percentage applies.
--fit|Fit unset settings to device memory|Let llama.cpp adjust otherwise-unset context/offload choices to fit available device memory.|On can avoid out-of-memory startup by lowering/changing chosen settings; off leaves those automatic fitting adjustments disabled.|This does not override every explicit setting or guarantee all workloads fit. Read the final context/offload allocation in startup output.
--fit-target|Free VRAM margin per device|Headroom the automatic fitter tries to leave on each device, in MiB.|Larger margins leave more VRAM unused by fitted model settings and may reduce offload/context; smaller margins fit more but leave less room for other work.|1024 → 2048 asks for roughly one extra GiB of free margin per affected device. This is a fitting target, not an allocation or a hard reservation.
--fit-ctx|Minimum fitted context|Smallest context the automatic fitter may choose.|Increase to protect a useful minimum context but make fitting harder; decrease to allow a smaller cache when VRAM is tight.|4096 → 8192 doubles the context floor. For a dense cache the minimum KV payload can roughly double; allocation/backend overhead remains separate.
`,['server','kv','performance']);
define('gpu','GPU & memory','Backend buffers & operations','weights',`
--repack|Repack weights for the backend|Allow a backend to rearrange weights into a format better suited to its kernels.|On can add startup work/temporary storage but help supported kernels; off avoids that step and may lower their throughput.|It does not change GGUF quantization or parameter count. Memory/speed differences depend on the backend's repacking implementation.
--no-host|Bypass host staging buffer|Change backend buffer allocation by bypassing the usual host buffer.|Enable only for a backend/layout that benefits from the extra-buffer path; disabling returns to ordinary host-buffer behavior.|This is a memory/backend option, unrelated to listen address or network access. No fixed RAM/VRAM saving can be promised.
--op-offload|Offload host tensor operations|Allow eligible CPU-side tensor operations to run on a device.|On can accelerate supported operations but add transfers/device buffers; off keeps those operations on the host.|Benefit depends on operation size and backend. This is distinct from weight-layer count and KV placement.
--rpc|Remote compute devices|Connect supported RPC backends to remote device servers.|Adding remote devices can increase available memory/compute but introduces network transfer and remote resource costs.|Network bandwidth/latency can dominate. This is remote inference computation, not the local API listen address or an MCP connection.
`);
define('context','Context & cache','Model loading & paging','loading',`
--load-mode|Model loading mode|Choose mapped, locked, ordinary or DirectIO weight loading.|mmap loads pages as needed; mlock prevents eligible pages from being swapped; mmap+mlock combines them; dio changes disk I/O. Modes are not ordered from slow to fast.|Locking 8 GiB of eligible pages can require roughly 8 GiB of available resident RAM, plus cache/buffers. It does not reduce GPU weight bytes or guarantee more tokens/s.
--lazy-mode|Read large tensors on demand|Allow supported tensor rows to be read from disk instead of remaining resident.|on can reduce resident RAM but add read latency; off keeps supported tensors resident; auto only applies above the runtime's size threshold.|The reviewed auto threshold is tensors larger than 4 GiB. Fast SSDs and access patterns matter; this is not a generic guarantee that all model weights become lazy.
`);
define('sampling','Sampling','Randomness & candidate selection','sample',`
--temp|Temperature|How strongly sampling favors high-probability tokens over alternatives.|Higher positive values flatten the distribution and encourage variety; lower values favor likely tokens. Very low/zero settings can select greedily.|0.4 → 0.8 is more randomness, not twice the creativity or half the quality. Effects depend on model and the other active samplers.
--top-k|Top-K candidates|Keep at most K of the highest-ranked token candidates.|Higher K permits more alternatives; lower K narrows choice. 0 disables this filter in the reviewed runtime.|K=1 leaves one candidate and is effectively greedy at this stage; K=40 permits up to forty. This does not change model size.
--top-p|Top-P probability mass|Keep the smallest high-ranked candidate set reaching the requested probability mass.|Higher values retain more probability mass and usually more alternatives; lower values make selection narrower. 1 disables this filter.|0.90 retains about 90% cumulative probability before later selection, not 90% of all vocabulary tokens.
--min-p|Relative minimum probability|Discard candidates too unlikely relative to the most probable token.|Higher values filter more aggressively; lower values keep more alternatives. 0 disables it.|At min-p 0.05 and a top token probability of 0.40, the cutoff is about 0.02 before renormalization. It is relative, not an absolute 5% threshold.
--top-nsigma|Logit standard-deviation filter|Limit candidates using distance from the top logit measured in standard deviations.|A larger allowed distance generally retains more candidates; a smaller one narrows the set. Negative disables it in the reviewed build.|This is a distribution-dependent cutoff, not a token count or a memory size. Test output quality with your other filters.
--typical|Locally typical sampling|Keep candidates whose information content is typical for the current distribution.|Lower p restricts retained probability mass more; p near 1 leaves more alternatives. 1 disables it.|Typicality differs from simply choosing the most probable tokens. A value of 0.9 is not a 10% quality/performance change.
--xtc-probability|XTC activation probability|How often the exclude-top-choices sampler is applied.|Increase to apply its diversity-inducing exclusion more often; decrease toward 0 to disable it.|0.1 → 0.5 changes activation from roughly 10% to 50% of sampling decisions, not a speed multiplier; output can become less predictable.
--xtc-threshold|XTC exclusion threshold|Probability threshold used to decide which very likely choices XTC can exclude.|Lower thresholds can make more top candidates eligible for exclusion; higher thresholds make exclusion harder. 1 disables it.|Interactively tune with XTC probability. Aggressive exclusion can hurt coherence; memory remains dominated by weights/KV.
--samplers|Sampler pipeline order|Which token-selection filters run, and in what sequence.|Adding, removing or reordering filters changes the final distribution; there is no universal better order.|top-k then top-p need not behave like top-p then top-k. Use semicolon-separated names supported by the selected executable.
--sampler-seq|Compact sampler sequence|Short-letter notation for the sampling pipeline.|Changing letters/order changes the same token-filtering process; it is not a CPU scheduling sequence.|Use this or the named sampler pipeline deliberately. Letter meanings and defaults are version-specific; check the executable help.
--seed|Sampling random seed|Choose a repeatable pseudo-random sampling sequence for comparison.|Changing the integer chooses another random sequence, not more or less randomness. The special random-seed value requests a fresh sequence.|Use one fixed seed when comparing settings. Identical seeds do not guarantee bit-identical output across backends, parallel workloads or versions.
--backend-sampling|Sample on the compute backend|Let the backend perform supported token sampling operations.|On can avoid some device-to-host sampling work; off follows the normal host path. Support and benefit vary.|Experimental in the reviewed build. It does not automatically accelerate model evaluation or reduce model-weight memory.
`);
define('sampling','Sampling','Repetition control','sample',`
--repeat-last-n|Repetition history window|Number of recent tokens considered by repetition penalties.|More history catches repeats farther back and adds history checking; less focuses on recent text. 0 disables this history-based penalty window.|64 → 128 doubles inspected token positions, not total model memory. Excessive penalties can prevent legitimate repeated names/code.
--repeat-penalty|Repeated-token penalty|Multiplicative adjustment discouraging recently used tokens.|Above 1 penalizes repeats more; 1 is neutral; values below 1 can encourage repetition.|1.1 → 1.2 is a change in the penalty formula, not a guaranteed 10% repetition reduction. Test prose and code separately.
--presence-penalty|Penalty for appearing at all|Add a penalty to a token if it has appeared in the considered history.|More positive values discourage any reuse; zero is neutral; negative values can encourage reuse.|Each present token gets the configured adjustment independent of its count. The impact depends on model logits, not a fixed percentage.
--frequency-penalty|Penalty per occurrence|Penalize tokens in proportion to how often they occur in the considered history.|Higher positive values increasingly discourage frequent tokens; zero is neutral; negative values encourage them.|At strength 0.2, five counted occurrences contribute about a 1.0 logit adjustment before other sampler operations. This is not a quality guarantee.
--dry-multiplier|DRY repetition strength|Overall strength of the penalty against repeated text sequences.|Increase to suppress long repeated passages more strongly; decrease toward 0 to disable DRY.|A strength of 2 applies twice the configured penalty magnitude of 1 for otherwise identical inputs, not twice the text quality.
--dry-base|DRY penalty growth|Base controlling how quickly repeated-sequence penalties grow beyond the allowed length.|Higher bases make long repetitions increasingly expensive; lower bases make growth gentler.|For the exponential component, base 2 grows by 2× per additional penalized token. Other DRY settings and detected matches still matter.
--dry-allowed-length|Unpenalized repeated length|How long a matching sequence may repeat before DRY penalizes it.|Increase to tolerate longer repeated phrases; decrease to start penalizing sooner.|2 → 4 allows two additional repeated tokens before this sequence penalty begins. Code/structured output may require legitimate repetition.
--dry-penalty-last-n|DRY history window|How much preceding text DRY searches for repeated sequences.|Increase to catch farther-back repetitions with more history work; decrease to limit its search. 0 disables the configured DRY penalty window.|64 → 256 expands the token-history ceiling fourfold, not model memory fourfold. Special negative values follow the installed version's help.
--dry-sequence-breaker|DRY sequence boundaries|Strings that split repetition matching into separate sequences.|Adding breakers stops DRY matching across those boundaries; removing them permits longer cross-boundary matches.|A newline breaker can separate paragraphs. Setting custom breakers replaces the defaults; none disables the breaker list rather than DRY itself.
`);
define('sampling','Sampling','Adaptive sampling','sample',`
--adaptive-target|Adaptive-P target probability|Guide adaptive sampling toward tokens near a chosen probability.|A higher/lower target changes which part of the candidate distribution is favored; negative disables the method.|Valid targets are 0–1 in the reviewed version. They are probability targets, not temperature, a quality score or a memory fraction.
--adaptive-decay|Adaptive-P smoothing|How much the adaptive target retains its previous state.|Higher values are steadier/slower to react; lower values respond more quickly to recent changes.|0.9 retains much more previous state than 0.1 at each update. This does not mean 90% of model memory is cached.
--dynatemp-range|Dynamic temperature range|Allow sampling temperature to vary around its base value.|A larger range permits larger changes between distributions; 0 disables dynamic temperature.|With base 0.8 and range 0.2, the intended range is around 0.6–1.0 before implementation limits; this is randomness variation, not an inference speed range.
--dynatemp-exp|Dynamic temperature response curve|Shape how distribution uncertainty maps to the dynamic temperature range.|Changing the exponent changes the response nonlinearly; it is not another temperature limit.|At zero dynamic range it has no useful effect. Compare generated text with fixed seeds rather than reading it as a speed/power exponent.
--mirostat|Mirostat sampling mode|Choose an adaptive entropy controller instead of the usual candidate filters.|0 disables it; 1 and 2 choose different algorithms, not progressively higher strength. Some normal filters are ignored while it is active.|Do not compare mode 2 as twice mode 1. Tune target entropy and learning rate, and check the sampler interactions in executable help.
--mirostat-lr|Mirostat learning rate|How quickly Mirostat changes its controller after a token.|Higher rates react faster but can oscillate; lower rates adapt more slowly and smoothly.|0.1 → 0.2 doubles the update coefficient, not generation speed or target entropy.
--mirostat-ent|Mirostat target entropy|Target surprise/uncertainty level of generated tokens.|Higher targets allow less predictable choices; lower targets favor more predictable output.|The parameter is an entropy target, not token count. It does not change the model's context capacity or parameter memory.
`);
define('chat','Templates & output','Response length & stopping','format',`
--predict|Output token limit|Maximum new tokens an answer may generate, separate from prompt/context length.|Increase to allow longer answers and longer total generation time; decrease to cap latency/output. It does not directly increase tokens/s.|At a measured 20 tokens/s, 200 generated tokens take roughly 10 s and 400 roughly 20 s, excluding prompt work. A maximum is not a promise to generate that many; negative sentinels are version-specific.
--ignore-eos|Ignore the normal end token|Prevent the model's end-of-sequence token from ending generation normally.|On can keep output going after a natural stop and consume the remaining limit/context; off respects the stop token.|A model that normally stops after 50 tokens may continue toward a 500-token limit. That increases elapsed work, not weight size.
--reverse-prompt|Stop text sequence|Stop generation when the specified text appears.|A more likely/shorter stop string can end answers earlier; a rare one may never appear. This is a stop condition, not a decoding speed setting.|Choose text that cannot accidentally occur in a desired answer. It can truncate valid prose/code if the marker is too broad.
--special|Show special tokens|Include visible representations of model control/special tokens in output.|On exposes formatting/control tokens for inspection; off produces cleaner user-facing text.|Usually a small output-format change. It does not add training knowledge or enlarge the context limit.
--escape|Interpret escape sequences|Interpret text escapes such as backslash-n as newline characters where supported.|On converts recognized escapes; off treats the relevant input literally.|The two characters backslash+n become one newline under escaping. Prompt tokenization may change; it is not a memory optimization.
`);
define('chat','Templates & output','Chat templates & infill','format',`
--jinja|Jinja chat formatting|Use the template engine that formats structured chat messages for the model.|On supports the model's Jinja chat template and tool formatting; off uses the supported alternative behavior.|Keep the model-compatible format. A wrong template can damage answers even while speed and memory look normal.
--chat-template|Inline chat template|Override how roles/messages are converted into the model's prompt.|Changing the template changes control tokens and prompt layout; it is unrelated to temperature sampling.|Prefer the GGUF's built-in template unless the model publisher provides another. More template text can consume more prompt tokens.
--chat-template-file|Chat template file|Read a custom Jinja chat template from a file.|Same formatting effect as an inline template; changing files does not change model weights.|Use a template intended for this exact model family. File size is not a model performance score.
--chat-template-kwargs|Template parameters (JSON)|Pass additional named values to the chat template, such as a supported thinking switch.|Effect depends entirely on which keys the template reads. More keys do not inherently mean more sampling or more compute.|For a supporting template, enable_thinking can change output length substantially; an unsupported key may have no effect.
--skip-chat-parsing|Return raw content parsing|Bypass the usual structured chat parser and place generated material in content.|On can leave reasoning/tool markers inside ordinary content; off permits supported structured extraction.|This changes response representation, not the number of model parameters. Clients expecting tool_calls or separated reasoning may need different handling.
--prefill-assistant|Continue an assistant prefix|Continue the final assistant message instead of always starting a fresh response.|On can constrain the beginning of an answer to a supplied prefix; off follows the non-prefill chat behavior.|Useful for compatible structured starts, but model/template support matters. The prefix consumes prompt tokens.
--spm-infill|Code infill ordering|Use suffix-prefix-middle ordering instead of prefix-suffix-middle for supported code models.|This is a format choice to match the model, not a larger/smaller setting.|Wrong infill ordering can make code completion ineffective. Use the order the chosen infill model expects.
`);
define('chat','Templates & output','Reasoning / thinking','format',`
--reasoning|Thinking mode|Enable, disable or automatically detect model/template-supported thinking.|On can add reasoning tokens/time; off requests non-thinking behavior where supported; auto follows the template/runtime.|This does not grant reasoning support to an incompatible model. Compare total generated tokens and wall time, not only tokens/s.
--reasoning-effort|Thinking effort hint|Pass a named effort level to a supporting chat template.|Higher levels can lead to longer/more deliberate thinking; lower levels can reduce response time. Exact behavior is model-defined.|high is not a fixed token multiplier and may be ignored by unsupported templates. Use a token budget when a supported hard limit is needed.
--reasoning-budget|Thinking token budget|Limit how many reasoning tokens are allowed before the runtime ends thinking.|Larger budgets permit more thinking time; smaller budgets end thinking earlier. -1 is unrestricted and 0 requests immediate end in the reviewed build.|At a measured 20 generated tokens/s, 1000 thinking tokens alone are roughly 50 s; 2000 roughly 100 s. Actual use can be below the cap and answer tokens add time.
--reasoning-budget-message|Budget-exhausted message|Text injected before closing the thinking section when its budget runs out.|Different messages can affect the transition into the answer; more text consumes additional prompt/state tokens.|This message is not the budget itself. Keep it short and compatible with the chosen model/template.
--reasoning-format|How reasoning is returned|Choose whether thought markers remain in content or are extracted into structured fields.|Changes visibility/response structure; hiding thought text does not necessarily prevent the model from generating it.|A shorter visible answer can still have spent time on hidden reasoning. Measure generated reasoning tokens/latency separately.
--reasoning-preserve|Keep earlier reasoning in history|Retain prior reasoning traces across chat history where the template supports it.|On can grow future prompts/context use; off can reduce repeated reasoning history and change later answers.|Keeping 1000 additional reasoning tokens uses roughly 1000 more prompt positions next time; it does not duplicate model weights.
`);
define('chat','Templates & output','Constrained output','format',`
--grammar|Inline output grammar|Restrict generated token sequences to a supplied grammar.|Stricter grammars narrow allowed output and can add token-filtering work; removing the constraint permits freer text.|Use for structural validity, not factual correctness. Large/ambiguous grammars can have materially higher filtering overhead.
--grammar-file|Output grammar file|Read a grammar that constrains the response from a file.|Same constraint tradeoff as inline grammar; file-based input is easier to maintain for complex rules.|A valid format does not guarantee a correct answer. Grammar compilation/filtering costs depend on its complexity, not just file length.
--json-schema|Inline JSON output schema|Constrain generated JSON to the supported subset of a schema.|More constraints restrict possible output; they may add filtering/setup work. Fewer constraints permit more JSON shapes.|A schema requiring one field does not make the field's value truthful. Not every JSON Schema construct is supported.
--json-schema-file|JSON schema file|Read the output schema from a file instead of inline JSON.|Changing schemas alters permitted output, not GPU weight placement.|Use the selected runtime's supported schema subset. Complex schemas can cost more setup/filtering time; no constant speed ratio applies.
`);
define('models','Models & adapters','Model sources','model',`
--model|Main GGUF model|Select the base model weights used for ordinary inference.|Larger or higher-precision models often need more memory and compute; smaller/lower-precision ones often fit and run more easily, with quality tradeoffs.|Use the Models picker for local files. Parameter count alone does not give file size: 8B at nominal 4 bits is roughly 4 GB of raw parameter bits before scales/other tensors, not an exact GGUF/VRAM estimate.
--model-url|Direct model download URL|Tell llama.cpp to obtain its model from a URL rather than only a local file.|A different URL may choose different weights/quantization. Downloading adds network/disk time; the URL itself has no inference speed effect.|An 8 GiB file takes at least about 80 s at an actual 100 MiB/s transfer rate, before verification/load overhead. A remote source can take precedence over the local picker.
--docker-repo|Docker model repository|Choose a model/quantization from a supported Docker Hub model repository.|Repository/tag selects the actual model; it is not the container runtime for MCP tools.|A tag can refer to a very different model size. Inspect the resolved model and quantization; this can trigger network downloads at launch.
--hf-repo|Hugging Face model repository|Choose a repository and optional quantization for llama.cpp's own model download.|Changing quantization/model changes weight size and possible quality/speed; a repository name alone is not a memory setting.|Specify user/repo and the supported quant suffix. This starts a server-managed source; the launcher's Models download manager is a separate workflow.
--hf-file|Exact Hugging Face GGUF file|Choose a specific repository file rather than relying on automatic quantization selection.|Selecting a smaller quantized file usually lowers weight memory; larger precision files usually require more memory. Quality/speed depend on model/backend.|This overrides automatic file selection for hf-repo. Ensure split shards/companions are available for the selected model.
--hf-token|Server-side Hugging Face token|Credential llama.cpp uses for its own restricted repository downloads.|A valid token can grant access; changing its text does not accelerate model inference or change quantization.|The launcher account token is separate from this server flag. Keep it private; credentials are omitted from public JSON and scrubbed from known display/log surfaces.
--offline|Use cached models only|Prevent llama.cpp's model retrieval from using network access.|On requires necessary files already cached/local; off permits supported downloads. This does not sandbox unrelated external tool processes.|Offline avoids download waits only when files are already present; it does not make a missing model available or reduce its memory use.
--override-kv|GGUF metadata overrides|Override named model metadata values, not attention KV-cache entries.|Changes can alter tokenization or architecture behavior; wrong values can prevent load or degrade answers.|This is not a cache-size control despite its name. Use only exact metadata overrides documented for the model.
--check-tensors|Validate tensor values on load|Check model tensors for invalid values during loading.|On adds startup validation work; off skips that explicit scan. It is mainly a diagnostic rather than a speed setting.|Large files can take longer to check. It does not repair corrupt weights or prove that outputs are factually correct.
`);
define('models','Models & adapters','Adapters & steering','adapter',`
--lora|LoRA adapter files|Load small learned changes on top of a compatible base model.|More adapters add adapter tensors and potentially inference work; removing them returns toward base-model behavior.|Adapters must match the base model. Several 100 MiB adapters add their own data, not full copies of the base model.
--lora-scaled|LoRA adapter strength|Load adapters with explicit influence strengths.|Higher absolute strength applies a stronger learned change; 0 neutralizes its influence but may leave its tensors loaded. Smaller strength moves toward base behavior.|0.5 versus 1.0 is half the adapter update coefficient, not half its RAM or a guaranteed halfway output.
--lora-init-without-apply|Load adapters inactive|Load adapter data but wait for a later API action before applying it.|On retains adapter memory without immediately changing inference; off applies loaded adapters normally.|Inactive adapters can still consume memory. Use when deliberately switching adapter influence through the server API.
--control-vector|Control vector files|Load vectors that steer hidden model activations in a chosen direction.|More vectors add steering data and change output behavior; they do not retrain or replace the base weights.|Compatibility and vector training matter. This is a behavioral steering feature, not a general quality or speed upgrade.
--control-vector-scaled|Control vector strength|Apply a steering vector with a specified coefficient.|Larger absolute values steer more strongly; smaller values steer less. Negative values can reverse the learned direction.|A coefficient of 0 may stop its influence while loaded data remains. Doubling strength does not double memory or guarantee a linear response.
--control-vector-layer-range|Steered layer range|Choose which inclusive model-layer range receives the steering vectors.|A wider range affects more layers; a narrower range localizes the steering. Quality effects are model/vector specific.|START=10 END=19 targets ten numbered layers. This is unrelated to how many layers are offloaded to GPU.
`);
define('models','Models & adapters','Images & video','media',`
--mmproj|Multimodal projector file|Load the companion encoder/projector required for a supported vision/audio model.|Selecting a companion enables that model's media path; it adds separate weights/work. Omitting an incompatible projector does not turn arbitrary text weights into a vision model.|Use the companion intended for the base model. Its file/tensors add to the base model's memory, with placement controlled separately.
--mmproj-url|Projector download URL|Download a compatible multimodal companion instead of providing its local path.|Changes download/setup, while the selected projector determines memory and encoder behavior.|Projector download size is separate from GGUF text weights. URLs may need network access at launch.
--mmproj-auto|Automatically select a projector|Allow automatic companion selection when the source/runtime supports it.|On can fetch/load an available companion; off avoids that automatic projector selection and can disable required media capability.|This can add a separate model download/allocation. Check which companion is resolved rather than assuming it is free.
--mmproj-offload|Run the media projector on GPU|Control GPU offload of the companion encoder/projector.|On can improve image/media encoding and consumes GPU memory; off puts eligible work in CPU/RAM and may be slower.|This does not change the text model's GPU layer count. The saving is the eligible projector/buffer allocation, not a fixed fraction of text weights.
--mmproj-device|Projector device|Choose where the companion encoder/projector is placed.|Selecting another GPU can rebalance VRAM but add transfers; none requests CPU placement where supported.|Use an actual device name reported by the executable. Main model and projector need not occupy the same GPU.
--image-min-tokens|Minimum image token budget|Minimum visual token count requested for dynamic-resolution vision models.|Increase to retain more image detail and increase encoding/prompt work; decrease to permit smaller representations.|256 → 512 doubles the minimum token budget, not necessarily resolution or accuracy. Only dynamic-resolution models using this option are affected.
--image-max-tokens|Maximum image token budget|Upper limit on visual tokens for supported dynamic-resolution vision models.|Increase to allow more detail and more work/cache use; decrease to cap media cost but possibly miss small details.|512 → 1024 doubles the allowed image-token ceiling. It does not double model weights or guarantee double image accuracy.
--mtmd-batch-max-tokens|Image encoding microbatch|Maximum image tokens encoded in one media-processing batch.|Increase for more parallel encoder work and potentially larger buffers; decrease to lower temporary memory and use more passes.|1024 → 2048 doubles the batch-token ceiling, not the image's final token count. Actual buffer growth depends on the encoder/backend.
--video-fps|Frames analyzed per second|Target sampling rate for video input.|Higher FPS analyzes more frames and costs more decoding/encoding/prompt work; lower FPS is cheaper but can miss short events.|For 10 seconds of video, 2 FPS selects about 20 frames and 4 FPS about 40 before decoder rounding/limits. Frame count can approximately double; speed/accuracy do not necessarily do so.
--video-timestamp-interval|Timestamp spacing|Milliseconds between inserted text timestamps for video.|Smaller intervals add more timestamp text; larger intervals use fewer markers and coarser time cues.|1000 ms inserts markers about every second; 5000 about every five seconds. This does not set video FPS or alter the model's weights.
--video-ffmpeg-dir|Video decoder directory|Where llama.cpp finds ffmpeg and ffprobe for supported video decoding.|Changing the directory chooses installed tools, not a quality or speed multiplier.|Use a compatible local installation. The actual codec/resolution, decoder and sampled frame count determine CPU/RAM cost.
--media-path|Allowed local media directory|Base directory for local file media references used by server requests.|Enabling a directory makes those supported relative media files available; a broader directory does not make encoding faster.|Choose only intended media files. Input sizes/frame counts determine memory; this option controls file access rather than resolution.
`,['server','media']);
define('models','Models & adapters','Router models','model',`
--models-dir|Router models directory|Directory advertised by the on-demand model router.|More available files add choices; they do not all load immediately. Use the Models folder control for this launcher's directory.|One directory containing ten models is not ten loaded models. Simultaneous loaded memory is controlled by router policy/workload and models-max.
--models-preset|Router preset file|INI configuration of per-model router settings.|Allows each routed model to use its own model/runtime choices; changing presets can substantially change per-model allocations.|A small INI file can describe many gigabytes of models. Confirm paths and per-model context/offload values in the preset.
--models-max|Maximum loaded router models|How many model workers the router may keep loaded simultaneously.|Increase to reduce model switching/unloading but permit much higher total RAM/VRAM; decrease to constrain concurrent loaded models. 0 means unlimited in the reviewed build.|If two loaded workers each need 6 GiB, together they need roughly 12 GiB plus router/overheads. This counts models, not request slots within one model.
--models-autoload|Load routed models on demand|Let an incoming request trigger loading an advertised model.|On is convenient but the first request can wait for loading; off requires explicit model loading before use.|A cold model can take seconds or longer depending on file/device speed. This is different from automatically loading every listed model at startup.
--alias|API model aliases|Names clients can use to identify this model through the API.|Adding aliases offers alternate names for the same configured model; it does not create more model instances.|Three aliases do not allocate three copies of weights. In router presets use unique names to avoid ambiguous selection.
--tags|Informational model tags|Attach descriptive labels to the model listing.|More tags improve organization but do not control routing or inference behavior.|Tags are metadata. They do not alter memory, compute or automatically select models for requests.
`);
define('api','API & server','Embedding & ranking tasks','network',`
--embedding|Embedding-only service|Restrict service to embedding use with a dedicated embedding model.|On selects an embedding workload instead of ordinary chat generation; off leaves the normal supported service behavior.|Use an embedding-trained model. Embedding throughput/sequence length are different metrics from generated chat tokens/s.
--rerank|Reranking endpoint|Enable ranking candidate documents with a compatible reranking model.|More/longer candidates mean more sequence evaluation and latency; simply enabling the endpoint does not make chat answers better.|Ranking 100 comparable documents involves more work than ranking 10. Use the correct model and measure documents/s or request latency.
--pooling|Embedding pooling method|How token-level features are combined into a sequence embedding or ranking output.|none, mean, cls, last and rank choose different output semantics, not increasing quality levels.|Use the method expected by the model and retrieval pipeline. A mismatched pooling method can produce poor retrieval despite valid-looking vectors.
--embd-normalize|Embedding normalization|How the output vector is scaled before being returned.|-1 disables normalization; 0/1/2 and larger values choose different normalization rules. This is not the vector dimension.|2 uses Euclidean/L2 normalization; 1 uses L1. Match the similarity metric expected by your search index rather than assuming higher is better.
`);
define('setup','API & server','Listen address','network',`
--host|Server listen address|Which local IP interfaces accept server connections.|127.0.0.1 limits access to this computer; 0.0.0.0 listens on all IPv4 interfaces; a specific local IP selects that interface.|Set this in Launch. Other devices connect to the computer's real LAN IP, not 0.0.0.0. This changes reachability, not model speed.
--port|Server listen port|TCP port used by the server listener.|Changing the number selects another listener port; a higher number is not faster.|Set this in Launch. For port 8080 clients use http://LAN-IP:8080; choose an available port in the launcher's accepted range.
`);
define('api','API & server','HTTP & browser access','network',`
--reuse-port|Share listener port|Allow supported socket arrangements to bind the same port.|On permits the runtime's reuse-port behavior; off preserves ordinary exclusive binding.|This does not share model weights or bypass the launcher's port-conflict preflight. Leave unset for a single launcher-owned server.
--path|Static website directory|Serve static web files from a directory.|Changing the path changes served files, not the text model or GPU settings.|Keep secrets outside the served directory. Static file size affects disk/network work; this is not the models directory.
--cors-origins|Allowed browser origins|Which websites browsers may let call this server.|A narrower origin list restricts browser clients; wildcard is broader. It does not bind/unbind network interfaces.|Use exact browser origins including scheme/port as appropriate. CORS is a browser access policy, not API authentication or a firewall.
--cors-methods|Allowed browser HTTP methods|HTTP methods permitted by browser CORS checks.|More methods permit more kinds of cross-origin browser request; fewer may block legitimate clients.|Methods such as GET and POST are request types. This changes compatibility/access policy, not tokens/s.
--cors-headers|Allowed browser request headers|Headers a browser may send cross-origin.|A broader list supports more client headers; a narrower one can block Authorization/content-type use if omitted.|Ensure required API headers are allowed. It does not create an API key or increase connection capacity.
--cors-credentials|Allow credentialed browser requests|Permit browser cross-origin credentials according to the runtime's CORS implementation.|On permits supported credentialed requests; off disallows that CORS behavior. Wildcard/origin reflection has version-specific behavior.|This is not the API-key value and does not enable TLS. Choose it to match the intended browser clients/origin policy.
--api-prefix|API path prefix|Serve endpoints under an extra URL path.|Changing it moves the API path and requires clients to use the same prefix; it does not change model computation.|With /llama and port 8080, clients use http://LAN-IP:8080/llama/... rather than the root path. Avoid a trailing slash as instructed by the executable.
--timeout|HTTP read/write timeout|Seconds allowed by the server's HTTP read/write timeout policy.|Increase to tolerate slow clients/longer waits; decrease to free stalled connections sooner but risk failed requests.|60 → 120 doubles this timeout allowance, not response speed or the generation token budget. Streaming/inference timeout semantics vary by runtime.
--sse-ping-interval|Streaming heartbeat interval|Seconds between keepalive pings on supported SSE streams.|Smaller positive intervals send more keepalives; larger ones send less traffic but may exceed proxy idle limits. -1 disables them in the reviewed build.|30 → 10 sends roughly three times as many heartbeat opportunities. Heartbeats are not generated text and do not increase model tokens/s.
--threads-http|HTTP request workers|Workers handling HTTP requests rather than the model's token calculations.|Increase for more concurrent HTTP handling; decrease to save worker overhead. Too many can create contention.|4 → 8 is eight requested HTTP workers, not eight model inference threads or eight loaded models. Consider parallel slots separately.
`);
define('api','API & server','Authentication & TLS','network',`
--api-key|API authentication keys|Keys clients must supply to authenticate model API requests.|Adding keys permits more credentials; changing key length/text does not change inference quality or speed.|Use client Authorization bearer credentials. This is separate from Hugging Face and MCP tokens; keep keys in private profiles rather than public exports.
--api-key-file|API key file|Load authentication keys from a local file, one per line.|More non-comment keys permit more credentials; the file does not load extra model copies.|Protect the file itself. The launcher reads a supported key for its own health/test requests; the file is not embedded into a shareable export.
--ssl-key-file|HTTPS private key file|PEM private key used by server-side TLS.|Enabling a matching key/certificate changes connections from HTTP to HTTPS and adds TLS work, not model weight memory.|Use it with the matching certificate. Clients must trust that certificate; the launcher does not bypass certificate verification.
--ssl-cert-file|HTTPS certificate file|PEM certificate paired with the TLS private key.|Changes encryption/identity setup; using a larger certificate chain is not an inference optimization.|A valid matching pair and client trust are required. Do not put the private key in a served static-files directory.
`);
define('api','API & server','Web UI configuration','network',`
--ui|Built-in browser chat|Enable llama.cpp's own browser interface.|On serves the web UI; off can leave supported API endpoints available without that interface.|This is the server's browser page, not this desktop launcher's GUI. It does not load a second copy of model weights.
--ui-config|Inline browser UI defaults|JSON defaults for llama.cpp's browser chat interface.|Changes UI behavior/defaults recognized by that version; more JSON keys do not inherently use more model memory.|This configures the server's web page, not launcher's theme/profiles. Per-chat options may still change actual request behavior.
--ui-config-file|Browser UI defaults file|Read browser UI defaults from a JSON file.|Same UI effect as inline configuration; file location is an organizational choice.|A UI default is not necessarily a hard server-side limit. Confirm which settings the installed server recognizes.
`);
define('api','API & server','Monitoring & mutable endpoints','network',`
--metrics|Prometheus metrics endpoint|Expose server measurements such as request/token performance.|On enables monitoring data; off avoids that endpoint. Scraping often adds some request/formatting work.|Metrics measure the workload; they do not make it faster. The launcher can display available metrics when enabled.
--slots|Request-slot monitoring|Expose information about the server's request slots.|On allows compatible clients to inspect slot state; off removes that monitoring endpoint.|Four slots are not four loaded weight models. Slot visibility does not itself increase concurrency or context allocation.
--props|Allow global property updates|Permit supported global settings to be changed through POST /props.|On exposes mutable server properties; off keeps that mutation endpoint disabled.|Enabling it does not apply a speed preset. Use appropriate API access control because clients can change supported global behavior.
`);
define('mcp','Tools & integrations','Native tools & MCP overrides','tools',`
--tools|Built-in server tools|Enable selected built-in agent tools for model use.|More enabled tools expand available actions and prompt/tool metadata; they can trigger external work when used.|Enabling a shell/file tool grants capabilities, not free model intelligence. This is distinct from merely listing tools in the launcher's MCP panel.
--tools-runtime|Tool execution environment|Choose whether built-in tools execute on the host or in a supported container/runtime.|Containers can add startup and process overhead; host execution avoids that layer but has different access boundaries.|docker:... or podman:... describes tool execution, not model weight installation. Runtime images/processes consume their own disk/RAM.
--mcp-servers-config|Native MCP configuration file|Provide raw MCP server definitions to llama.cpp.|More configured servers can add tool metadata, connections and subprocesses; fewer reduce that external surface/work.|Use either the launcher's connection form or these raw server flags, not both for the same launch. Testing discovery does not execute tools.
--mcp-servers-json|Inline native MCP definitions|Provide MCP server definitions as an inline JSON value.|Same integration effect as a config file; inline credentials are still secrets and must stay private.|Use the structured Connections form for the normal workflow. This raw override is omitted from public export and redacted in known previews/logs.
--ui-mcp-proxy|Browser MCP CORS proxy|Enable the server web UI's experimental proxy to MCP endpoints.|On allows the proxy behavior and its network work; off keeps it disabled. It does not set the launcher's MCP URL.|This adds a network access capability. The upstream documentation cautions against enabling it in untrusted environments.
--agent|Built-in agent capabilities preset|Enable the upstream agent preset including tools/proxy capabilities.|On expands the actions available to agent workflows; off avoids that preset. It is not a stronger model or a speed mode.|Experimental and intended for controlled environments. Review exactly which tools/proxy features the selected runtime enables.
`);
define('logs','Logging','Server diagnostics','log',`
--perf|Internal performance timings|Collect internal libllama timing diagnostics.|On adds timing instrumentation; off avoids that measurement work. This does not tune CPU/GPU arithmetic.|Useful for comparisons; instrumentation can itself add overhead. Timings and verbose text logs are different settings.
--log-disable|Disable server logging|Suppress the server's own diagnostic output.|On reduces diagnostic visibility and log I/O; leaving logs enabled helps diagnose model/load errors.|This does not stop API requests or free model weights. Launcher rotation already caps its captured streams; separate server files have their own behavior.
--log-file|Additional server log file|Write native server logs to the specified file.|A separate path adds direct file I/O and disk growth. It can contain information not covered by the launcher's captured-stream scrubbing.|This file is outside the launcher's 60 MiB rotating log cap. Choose an appropriate location and manage its size/privacy separately.
--log-jsonl|Machine-readable JSON logs|Write one JSON log record per line to standard output.|On helps log parsers and disables color escapes; off uses the ordinary format.|Formatting changes bytes written, not model quality. High event volume still costs disk/CPU regardless of JSON formatting.
--log-colors|Log color policy|Choose ANSI color output on, off or automatic.|Off removes terminal escape codes; on adds colors; auto follows the output target.|Usually negligible model-speed/RAM effect. File/GUI log readers often benefit from plain text.
--verbose|All diagnostic messages|Enable the most detailed native server logging.|On can produce much more output and overhead; off returns to the configured verbosity threshold.|Useful temporarily for diagnosis. It is not a performance enhancement and can expose prompt/configuration detail in native outputs.
--verbosity|Log detail threshold|Highest severity/detail level of native messages to keep.|Higher levels retain more detail and potentially more I/O; lower levels retain fewer messages.|The reviewed levels run 0 generic through 5 debug, with 3 info. Going 3 → 5 can grow logs substantially; not by a predictable fixed ratio.
--log-prefix|Log message prefixes|Include context prefixes in native log messages.|On adds labeling useful for tracing; off removes that prefix text.|Small per-line formatting/disk overhead. It does not affect model parameter allocation.
--log-timestamps|Log timestamps|Include time information in native log records.|On helps correlate events; off makes lines shorter.|Adds a timestamp per message, not a fixed inference delay. Overall overhead follows the number of emitted messages.
--log-prompts-dir|Prompt debugging directory|Write prompt-debug information to a separate directory.|Enabling it adds disk writes and retains prompt content; leaving it unset avoids this debug output.|These files are outside launcher stream rotation/redaction and can contain private conversations. Use only for deliberate debugging and manage their disk/privacy separately.
`);
define('advanced','Utilities','Informational commands (exit)','utility',`
--help|Print executable help|Show the installed binary's supported command-line options.|This command normally exits after printing; it is not an inference configuration to add to a launch.|Use Read executable options in Launch. The actual installed help determines valid syntax/defaults for all settings.
--version|Print runtime version|Show build/version information for the installed executable.|Normally prints then exits; choosing it as a server startup override would not start a normal serving session.|Use runtime/version information for compatibility checks. A larger version number is not a measured speed improvement.
--cache-list|List cached models|Print models already known to the runtime's download cache.|Lists cached files rather than loading all their weights, and normally exits.|This cache listing is separate from the launcher's Models folder scan. Cached disk files are not necessarily loaded models.
--completion-bash|Bash completion script|Print shell-completion setup for supported command options.|One-time shell convenience; does not change runtime computation.|Not useful as a long-running server launch flag. It prints script text rather than improving inference.
--list-devices|List available compute devices|Ask this executable which backend devices it can enumerate.|Normally prints then exits; it does not offload weights by itself.|A listed GPU establishes enumeration, not successful execution of every model/kernel. Use its identifiers for device settings.
`);
define('sampling','Sampling','Explicit token preferences','sample',`
--logit-bias|Token probability bias|Add a positive/negative adjustment to specific token IDs before sampling.|More positive favors the token; more negative suppresses it. This targets a tokenizer ID, not arbitrary text or a percentage.|Before other filters, a +1 logit shift multiplies that token's relative odds by about e (2.72); renormalization and sampling still matter. Strong bans can break desired output.
`);
define('advanced','Speculative decoding','Speculation strategy','spec',`
--spec-type|Speculative decoding method|Choose draft-model or history-based proposal methods for the target model to verify.|A good proposal method can emit multiple accepted tokens per target pass; bad proposals add rejected work. none disables speculation.|Draft methods can require additional weights; n-gram methods reuse patterns without a second model. Compare accepted tokens per step and actual tokens/s, not only proposal count.
--spec-default|Automatic speculation configuration|Request the runtime's recommended speculative setup where supported.|Can choose compatible speculation settings; disable/unset it for a normal baseline. The selected model and runtime determine what is available.|A preset is not a guaranteed speedup. Check the resolved method, draft model/memory and acceptance in server diagnostics.
--spec-draft-model|Draft model file|Smaller/compatible model used to propose tokens for the main model.|A faster draft can reduce proposal cost but may predict less accurately; a larger draft can improve acceptance while costing more compute/memory.|An extra 1 GiB draft requires its own weights plus draft KV/compute buffers; it is not free because the main model is already loaded.
--spec-draft-hf|Draft model repository|Repository/quantization used to retrieve the proposal model.|Changing it selects a different draft with its own size/speed/acceptance tradeoff. It may download data at launch.|The target model is unchanged. Verify model/tokenizer compatibility and total memory for both models before increasing context/offload.
--spec-draft-n-max|Maximum draft tokens|Most tokens proposed in one speculative step.|Increase to potentially accept longer runs but spend more on rejected proposals; decrease to keep proposal overhead small.|3 → 6 doubles the proposal ceiling, not generation speed. If typical acceptance is only 1–2 tokens, the extra proposals may be wasted work.
--spec-draft-n-min|Minimum draft length|Minimum proposed length used by the supported draft strategy.|Higher minima demand longer proposal work and can reduce flexibility; lower minima allow shorter drafts.|Keep it consistent with the maximum and selected method. The count controls proposals, not the final answer's maximum length.
--spec-draft-p-min|Draft confidence cutoff|Minimum proposal probability used by supported greedy draft logic.|Increase to reject low-confidence proposals earlier, often shortening drafts; decrease to permit more uncertain proposals and possible rejection overhead.|0.2 requires more draft confidence than 0.05; a draft probability is not the target model's acceptance rate or a guaranteed speedup.
--spec-draft-p-split|Draft branching threshold|Probability parameter used by supported speculative splitting/branching logic.|Changes which proposal branches are considered. Effect depends on strategy; it is not a universal higher-is-faster slider.|The reviewed command help names a split probability but does not establish a cross-strategy cost/speed formula. Keep its default unless tuning the particular implementation.
--spec-draft-sampling|How draft tokens are chosen|Choose greedy proposals or supported probabilistic proposal/verification.|Greedy takes a most-likely candidate; probabilistic uses sampling with target verification. These are algorithms, not low/high quality levels.|Compatible target verification is essential. Compare acceptance and final sampling behavior with the installed version's chosen strategy.
--spec-draft-backend-sampling|Draft sampling on backend|Perform supported draft-token selection on the device backend.|On may reduce draft sampling transfers/host work; off uses the ordinary alternative. Backend support determines whether it helps.|This is separate from target backend sampling. It cannot remove draft weight/KV memory or guarantee faster verification.
`,['server','args','speculative']);
for(const [flag,base,title,group] of [
 ['--spec-draft-type-k','--cache-type-k','Draft key cache precision','Draft cache & placement'],['--spec-draft-type-v','--cache-type-v','Draft value cache precision','Draft cache & placement'],
 ['--spec-draft-device','--device','Draft compute devices','Draft cache & placement'],['--spec-draft-ngl','--gpu-layers','Draft GPU weight layers','Draft cache & placement'],
 ['--spec-draft-override-tensor','--override-tensor','Draft tensor placement','Draft cache & placement'],['--spec-draft-cpu-moe','--cpu-moe','Draft CPU MoE experts','Draft cache & placement'],['--spec-draft-n-cpu-moe','--n-cpu-moe','Draft CPU MoE layer count','Draft cache & placement'],
 ['--spec-draft-threads','--threads','Draft generation CPU threads','Draft CPU threads'],['--spec-draft-threads-batch','--threads-batch','Draft prompt CPU threads','Draft CPU threads'],
 ['--spec-draft-cpu-mask','--cpu-mask','Draft CPU affinity mask','Draft CPU placement'],['--spec-draft-cpu-range','--cpu-range','Draft CPU core range','Draft CPU placement'],['--spec-draft-cpu-strict','--cpu-strict','Strict draft CPU placement','Draft CPU placement'],
 ['--spec-draft-cpu-mask-batch','--cpu-mask-batch','Draft prompt affinity mask','Draft CPU placement'],['--spec-draft-cpu-strict-batch','--cpu-strict-batch','Strict draft prompt placement','Draft CPU placement'],
 ['--spec-draft-prio','--prio','Draft scheduling priority','Draft scheduling'],['--spec-draft-poll','--poll','Draft busy polling','Draft scheduling'],['--spec-draft-prio-batch','--prio-batch','Draft prompt scheduling priority','Draft scheduling'],['--spec-draft-poll-batch','--poll-batch','Draft prompt busy polling','Draft scheduling'],
])variant(flag,base,{tab:'advanced',category:'Speculative decoding',group:`Speculation · ${group}`,title,prefix:'Draft model only, not the target model:'});
for(const flag of ['--poll-batch','--spec-draft-poll','--spec-draft-poll-batch'])reviewedGuides.get(flag).scale='The reviewed executable uses 0/1 for this waiting-policy switch. 1 enables polling and 0 disables it; neither means a specified percentage speedup.';
define('advanced','Speculative decoding','Speculation · n-gram history','spec',`
--spec-ngram-mod-n-min|N-gram-mod minimum proposal|Minimum draft run requested by the n-gram-mod history strategy.|A larger minimum requests longer candidate runs and can waste verification work if matches are weak; a smaller one accepts shorter opportunities.|48 → 64 increases a proposal-length bound, not model context or a guaranteed acceptance count. Keep min/max consistent.
--spec-ngram-mod-n-max|N-gram-mod maximum proposal|Maximum history-derived token run proposed by n-gram-mod.|Increase to exploit long repetitive matches; decrease to limit speculative verification work and rejected tokens.|64 → 128 doubles the proposed-token ceiling, not generated tokens/s. Benefits depend on repetition in the actual request/history.
--spec-ngram-mod-n-match|N-gram-mod lookup length|How many history tokens must match when finding a continuation.|Longer keys are more selective and may miss useful matches; shorter keys find more candidates that may be less reliable.|A 24-token key requires a longer repeated suffix than a 12-token key. This is not the model's context limit.
--spec-ngram-simple-size-n|Simple n-gram lookup length|Token-key length used to look up repeated continuations in ngram-simple.|Increase for stricter/rarer matches; decrease for more frequent but potentially weaker matches.|12 → 24 doubles required key length, not speed or model memory. Use repetitive workloads to assess whether matches are useful.
--spec-ngram-simple-size-m|Simple n-gram proposal length|Length of candidate continuation ngram-simple may propose after a match.|Higher values allow longer candidate runs but can add rejected verification work; lower values cap that work.|48 → 96 doubles the proposal-length ceiling, not accepted token count. No second draft-model weights are needed for this history method.
--spec-ngram-simple-min-hits|Simple n-gram evidence threshold|How many matching observations are required before trusting a history proposal.|Higher thresholds require more repeated evidence and reduce opportunities; lower ones enable proposals sooner.|1 → 3 requires three observations rather than one. This can improve confidence while leaving fewer opportunities to accelerate generation.
--lookup-cache-static|Static speculation lookup cache|Read a prebuilt continuation lookup table that generation does not update.|A larger/more relevant table may find more useful proposals but requires storage/loading memory; an irrelevant one adds little benefit.|This is history/lookup data, not the active attention KV cache. A file twice as large does not imply twice the hit rate or speed.
--lookup-cache-dynamic|Learning speculation lookup cache|Use a lookup table that can be updated by generated text.|Can gain useful repeated continuations over time, with lookup/update and growing storage/memory costs.|Workload repetition determines benefit. Do not confuse it with cache-ram or the main model's quantized attention cache.
`,['server','args','speculative']);
for(const method of ['map-k','map-k4v'])for(const [suffix,base,title] of [
 ['size-n','--spec-ngram-simple-size-n','lookup length'],['size-m','--spec-ngram-simple-size-m','proposal length'],['min-hits','--spec-ngram-simple-min-hits','evidence threshold'],
])variant(`--spec-ngram-${method}-${suffix}`,base,{title:`N-gram ${method} ${title}`,prefix:`Applies to ngram-${method}, not ngram-simple:`});
define('advanced','Speculative decoding','Speculation · synthetic benchmarks','spec',`
--spec-synth-len|Synthetic acceptance length|Force a synthetic mean acceptance length for benchmarking speculative mechanics.|Higher values simulate longer accepted runs; lower values simulate shorter runs. These are artificial acceptance conditions.|Includes the target token. Synthetic improvements are not evidence that a real draft model will reach that acceptance or speed on user prompts.
--spec-synth-rates|Synthetic acceptance probabilities|Artificial per-position acceptance probabilities for benchmarking.|Higher probabilities simulate more acceptance; lower ones simulate more rejected work.|A sequence of probability values is not a measured acceptance trace. Leave unset for real quality/speed evaluations.
`,['args','speculative']);
define('advanced','Speculative decoding','Legacy speculation flags','spec',`
--draft|Legacy maximum draft tokens|Old name for a proposal-length control; removed in the reviewed executable.|Do not enable when the selected help says removed. Use spec-draft-n-max or the matching n-gram maximum instead.|Older executables may still implement this name. Follow that executable's help; the launcher preserves raw syntax/defaults alongside this guide.
--draft-min|Legacy minimum draft tokens|Old minimum-draft control removed in the reviewed executable.|Use the selected method's supported minimum proposal flag instead of passing a removed argument.|This is not an output length limit. Read the installed help before using a legacy name from an older profile.
--spec-ngram-size-n|Legacy n-gram lookup length|Old shared lookup-length flag replaced by method-specific options.|Use spec-ngram-simple/map-k/map-k4v-size-n or the relevant n-gram-mod match option supported by the executable.|The selected method determines the correct replacement; a common legacy value is not guaranteed meaningful for every new strategy.
--spec-ngram-size-m|Legacy n-gram proposal length|Old shared proposal-length flag replaced by method-specific options.|Use the matching method's size-m/maximum proposal option where supported.|Do not add a removed flag to launch arguments. Older binaries can differ; preserve their original help for compatibility.
--spec-ngram-min-hits|Legacy n-gram hit threshold|Old shared minimum-observation flag replaced by method-specific thresholds.|Use the specific n-gram method's supported min-hits setting.|A removed flag can make startup fail rather than tune performance. Migrate it explicitly when changing runtime versions.
`,['server','args']);
define('models','Models & adapters','Idle model unloading','loading',`
--sleep-idle-seconds|Unload after idle time|How long a model may sit idle before entering its supported sleep/unload state.|A shorter timeout can release idle resources sooner but trigger more reload delays; a longer one keeps warm memory longer. -1 disables sleeping in the reviewed build.|60 → 300 waits five times longer before sleep, not five times the inference speed. Freed GPU/RAM and wake time depend on backend, mapping and model size.
`);
define('models','Models & adapters','Model download presets','model',`
--embd-gemma-default|EmbeddingGemma preset|Request the upstream default EmbeddingGemma setup.|Selects a particular embedding-model preset and may download weights. It does not turn the current chat model into an embedding model.|Check the resolved files/quantization and embedding configuration; the preset name is not a memory-fit guarantee.
--fim-qwen-1.5b-default|Qwen Coder 1.5B preset|Request the upstream small Qwen 2.5 Coder infill preset.|Smaller weight models often fit more easily and evaluate faster than larger members, with capability tradeoffs.|1.5B is nominal parameter count, not 1.5 GiB memory. Quantization, cache, buffers and actual files determine allocation.
--fim-qwen-3b-default|Qwen Coder 3B preset|Request the upstream Qwen 2.5 Coder 3B infill model preset.|Changes model choice and may download files; compare its coding quality and measured speed with smaller/larger candidates.|3B is about twice 1.5B parameters, not a guarantee of twice the total RAM or half the speed across different configurations.
--fim-qwen-7b-default|Qwen Coder 7B preset|Request the upstream Qwen 2.5 Coder 7B infill model preset.|A larger model generally needs more weight storage/work, with possible capability gains; it can exceed a smaller GPU's budget.|A nominal 7B 4-bit parameter payload is about 3.5 GB before quantization scales/other tensors and runtime memory. Inspect actual files, not just this arithmetic.
--fim-qwen-7b-spec|Qwen 7B speculative infill preset|Request the 7B target plus the upstream smaller draft setup.|Can improve coding throughput when proposals match, but adds draft weights/cache/compute and can be slower with poor acceptance.|Budget for both models plus context/buffers. This is not the same memory footprint as a standalone 7B model.
--fim-qwen-14b-spec|Qwen 14B speculative infill preset|Request the upstream 14B target and draft infill setup.|Larger target weights increase memory/work; drafting adds its own costs and only helps with suitable acceptance.|The preset's model count/quantization matters. It is not guaranteed to fit or run faster simply because speculation is enabled.
--fim-qwen-30b-default|Qwen Coder 30B A3B preset|Request the upstream Qwen3 Coder 30B A3B preset.|MoE activates only part of the parameters for each token, but all required expert weights still need storage/placement.|30B total and roughly 3B active does not mean only a dense 3B model's weight memory. Check the MoE GGUF and expert placement.
--gpt-oss-20b-default|gpt-oss 20B preset|Request the upstream gpt-oss 20B model preset.|Selects different architecture/weights and may download them. Quality, active compute and cache behavior are model-specific.|The name is total nominal parameter scale, not a VRAM figure. Consult the resolved file size and model resource estimate.
--gpt-oss-120b-default|gpt-oss 120B preset|Request the upstream larger gpt-oss model preset.|A much larger total weight set can need substantial RAM/VRAM even when only some experts are active.|120B is not 120 GiB by definition, and active parameters do not eliminate storage of other required experts. Inspect quantization and placement.
--vision-gemma-4b-default|Gemma 3 4B vision preset|Request the upstream smaller Gemma 3 vision model setup.|Adds the supported vision path/projector as well as text weights; media encoding adds work beyond text-only generation.|Do not budget from text GGUF alone. Projector, image tokens, context and backend buffers need additional memory.
--vision-gemma-12b-default|Gemma 3 12B vision preset|Request the upstream larger Gemma 3 vision model setup.|Usually requires more weight memory/work than the smaller preset, plus projector/media processing; quality/speed are workload dependent.|12B versus 4B is about 3× nominal parameters, not a universal 3× RAM or 1/3 speed prediction for the complete application.
`);

const compatibilityAliases = {'--n-predict':'--predict','--n-gpu-layers':'--gpu-layers','--temperature':'--temp','--typical-p':'--typical','--embeddings':'--embedding','--reranking':'--rerank'};
/** @param {{flag:string,aliases?:string[]}} option @returns {import('./option-guide-types').OptionGuide} */
export function guideFor(option) {
  const aliases=option.aliases||[option.flag];
  for(const flag of aliases){const guide=reviewedGuides.get(flag)||reviewedGuides.get(compatibilityAliases[flag]);if(guide)return guide;}
  return {flag:option.flag,title:option.flag,tab:'advanced',category:'Version-specific',group:'Unreviewed executable options',reviewed:false,
    summary:'This executable has an option not covered by the reviewed guide. Its original help is shown below.',
    change:'No direction of change has been verified for this version-specific option. Use the installed executable documentation.',
    scale:'No numerical resource or speed effect has been verified. Measure this option with the selected runtime/model instead of assuming a gain.',
    speed:'Not quantified for this executable option.',vram:'Not quantified for this executable option.',ram:'Not quantified for this executable option.',sources:[sources.server]};
}
